1	using GritTrack.Api.Data;
2	using GritTrack.Api.Models;
3	using Microsoft.EntityFrameworkCore;
4	
5	namespace GritTrack.Api.Repositories;
6	
7	/// <summary>Stores courses in SQL Server through EF Core. Same promises as the JSON repo, different home.</summary>
8	public class SqlCourseRepository : ICourseRepository
9	{
10	    private readonly GritTrackDbContext _context;
11	
12	    public SqlCourseRepository(GritTrackDbContext context)
13	    {
14	        _context = context;
15	    }
16	
17	    /// <inheritdoc />
18	    public Task<List<Course>> GetAllAsync(CancellationToken cancellationToken)
19	        => _context.Courses.AsNoTracking().OrderBy(c => c.Id).ToListAsync(cancellationToken);
20	
21	    /// <inheritdoc />
22	    public Task<Course?> GetByIdAsync(int id, CancellationToken cancellationToken)
23	        => _context.Courses.FirstOrDefaultAsync(c => c.Id == id, cancellationToken);
24	
25	    /// <inheritdoc />
26	    public Task<Course?> GetByCourseCodeAsync(string courseCode, CancellationToken cancellationToken)
27	    {
28	        // the column compares without caring about upper or lower case, same as the JSON repo
29	        var trimmedCode = courseCode.Trim();
30	        return _context.Courses.FirstOrDefaultAsync(c => c.CourseCode == trimmedCode, cancellationToken);
31	    }
32	
33	    /// <inheritdoc />
34	    public async Task<Course> AddAsync(Course course, CancellationToken cancellationToken)
35	    {
36	        // SQL Server hands out the id when it saves
37	        _context.Courses.Add(course);
38	        await _context.SaveChangesAsync(cancellationToken);
39	        return course;
40	    }
41	
42	    /// <inheritdoc />
