// ============================================================================
// GritTrack API - backend for the GritTrack MAUI app
// connects mobile app to course/gpa data, handles auth, does the heavy lifting
// ============================================================================

using GritTrack.Api.Configuration;
using GritTrack.Api.Data;
using GritTrack.Api.Repositories;
using GritTrack.Api.Services;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Mvc.ModelBinding.Metadata;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
using System.Text;

// grab SQL password from .env before anything else runs - it's gitignored so we're safe
DotEnvLoader.Load(Directory.GetCurrentDirectory());

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers(options =>
{
    // validation errors use camelCase field names to match the JSON the client sent
    // otherwise you get "CourseCode" errors when you sent "courseCode" - super annoying
    options.ModelMetadataDetailsProviders.Add(new SystemTextJsonValidationMetadataProvider());
});

builder.Services.AddOpenApi();
builder.Services.AddProblemDetails();

// pick your poison: JSON file for local dev, SQL Server for real deployments
// service layer doesn't care which one - it just sees ICourseRepository
var dataSource = builder.Configuration["DataSource"] ?? DataSources.Json;
switch (dataSource)
{
    case DataSources.Json:
        // singleton because everyone shares one file - scoped would be chaos
        builder.Services.AddSingleton<ICourseRepository, JsonCourseRepository>();
        break;

    case DataSources.SqlServer:
        // scoped to match DbContext lifetime
        builder.Services.AddDbContext<GritTrackDbContext>(options =>
            options.UseSqlServer(SqlConnectionStringFactory.Build(builder.Configuration)));
        builder.Services.AddScoped<ICourseRepository, SqlCourseRepository>();
        break;

    default:
        throw new InvalidOperationException(
            $"DataSource '{dataSource}' is invalid. Use '{DataSources.Json}' or '{DataSources.SqlServer}'.");
}

builder.Services.AddScoped<ICourseService, CourseService>();

// auth toggle: off = anyone can write (good for testing), on = need a token
// GETs are always public because grades aren't sensitive data (yet?)
builder.Services.Configure<AuthOptions>(builder.Configuration.GetSection(AuthOptions.SectionName));
var authOptions = builder.Configuration.GetSection(AuthOptions.SectionName).Get<AuthOptions>() ?? new AuthOptions();
builder.Services.AddSingleton<IJwtTokenService, JwtTokenService>();

if (authOptions.Enabled)
{
    // fail fast if secrets are missing - better than cryptic errors on first login
    ValidateAuthSettings(authOptions);

    builder.Services
        .AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidIssuer = authOptions.Issuer,
                ValidateAudience = true,
                ValidAudience = authOptions.Audience,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(authOptions.SigningKey!)),
                ClockSkew = TimeSpan.FromSeconds(30)
            };
        });

    builder.Services.AddAuthorizationBuilder()
        .AddPolicy(AuthPolicies.WriteAccess, policy => policy.RequireAuthenticatedUser());
}
else
{
    // same policy name but auto-pass - controller code stays unchanged
    builder.Services.AddAuthorizationBuilder()
        .AddPolicy(AuthPolicies.WriteAccess, policy => policy.RequireAssertion(_ => true));
}

var app = builder.Build();

// auto-migrate on startup - no manual EF commands needed
if (dataSource == DataSources.SqlServer)
    await ApplyMigrationsAsync(app);

// global exception handler - no try/catch spam in every action
app.UseExceptionHandler();

if (app.Environment.IsDevelopment())
{
    app.MapOpenApi();
}

app.UseHttpsRedirection();

// 401 if you're missing a token on protected routes
if (authOptions.Enabled)
    app.UseAuthentication();
app.UseAuthorization();

app.MapControllers();

// log what mode we're running in - helps debug "why did this fail" issues
app.Logger.LogInformation("Data source: {DataSource}", dataSource);
app.Logger.LogInformation("Auth: {AuthState}", authOptions.Enabled ? "ON" : "OFF");

app.Run();

// yells at you if auth is on but you forgot to set the secrets
// use: dotnet user-secrets set "Auth:SigningKey" "something-long-and-random"
static void ValidateAuthSettings(AuthOptions authOptions)
{
    const int minimumSigningKeyLength = 32;
    var problems = new List<string>();

    if (string.IsNullOrWhiteSpace(authOptions.SigningKey) || authOptions.SigningKey.Length < minimumSigningKeyLength)
        problems.Add($"Auth:SigningKey is missing or shorter than {minimumSigningKeyLength} characters");
    if (string.IsNullOrWhiteSpace(authOptions.DemoPassword))
        problems.Add("Auth:DemoPassword is missing");

    if (problems.Count == 0)
        return;

    throw new InvalidOperationException(
        $"Auth:Enabled is true but {string.Join(" and ", problems)}. " +
        "Set them with: dotnet user-secrets set \"Auth:SigningKey\" \"<long random text>\" " +
        "and dotnet user-secrets set \"Auth:DemoPassword\" \"<your demo password>\" " +
        "(run from the GritTrack.Api folder), or set Auth:Enabled to false.");
}

// applies EF migrations with retry - SQL Server containers lie about being ready
// (the retry rules live in DatabaseMigrationRunner so they can be tested)
static Task ApplyMigrationsAsync(WebApplication app)
    => DatabaseMigrationRunner.RunWithRetryAsync(async () =>
    {
        using var scope = app.Services.CreateScope();
        var context = scope.ServiceProvider.GetRequiredService<GritTrackDbContext>();
        await context.Database.MigrateAsync();
    }, app.Logger);

using GritTrack.Models;

namespace GritTrack.Services
{
    // stand-in for ICourseRepository — just a list in memory, not a real
    // backend. registered as a Singleton so it survives navigation, but
    // it resets every time the app fully restarts. swap it for a real
    // database later by writing a new class that uses ICourseRepository
    public class InMemoryCourseRepository : ICourseRepository
    {
        private readonly List<Course> _courses;

        public InMemoryCourseRepository()
        {
            _courses = new List<Course>
            {
                new Course { ID = 1, Name = "Programming Fundamentals", CourseCode = "CS-101", Instructor = "Staff", Credits = 3, CurrentGrade = "A-", GradePoints = 3.7 },
                new Course { ID = 2, Name = "Database Concepts and Design", CourseCode = "CS-210", Instructor = "Staff", Credits = 3, CurrentGrade = "B+", GradePoints = 3.3 },
                new Course { ID = 3, Name = "Web Development I", CourseCode = "CS-150", Instructor = "Staff", Credits = 3, CurrentGrade = "A", GradePoints = 4.0 }
            };
        }

        public Task<List<Course>> GetCoursesAsync()
        {
            // returning a copy so nothing outside this class can mess with
            // the real list by accident
            return Task.FromResult(new List<Course>(_courses));
        }

        public Task<Course> SaveCourseAsync(Course course)
        {
            // a brand new course (ID 0) gets the next free ID, like a database would
            if (course.ID == 0)
                course.ID = _courses.Count == 0 ? 1 : _courses.Max(existing => existing.ID) + 1;

            int index = _courses.FindIndex(existing => existing.ID == course.ID);
            if (index >= 0)
                _courses[index] = course;
            else
                _courses.Add(course);

            return Task.FromResult(course);
        }

        public Task DeleteCourseAsync(int courseId)
        {
            _courses.RemoveAll(course => course.ID == courseId);
            return Task.CompletedTask;
        }

        public Task<List<Assignment>> GetAssignmentsLocalAsync(int courseId)
        {
            var course = _courses.FirstOrDefault(candidate => candidate.ID == courseId);
            return Task.FromResult(course is null ? new List<Assignment>() : new List<Assignment>(course.Assignments));
        }

        public Task<AssignmentImportResult> SaveAssignmentsLocalAsync(int courseId, IEnumerable<Assignment> assignments)
        {
            var assignmentList = assignments.ToList();
            var course = _courses.FirstOrDefault(candidate => candidate.ID == courseId);
            if (course is null)
                return Task.FromResult(new AssignmentImportResult(0, assignmentList.Count, new List<Assignment>()));

            foreach (var assignment in assignmentList)
                assignment.CourseID = courseId;

            // same duplicate rule as the real store: same title + due day is skipped
            var result = AssignmentDuplicateRule.Filter(course.Assignments, assignmentList);
            course.Assignments.AddRange(result.AddedAssignments);

            return Task.FromResult(result);
        }
    }
}

using System.Text.Json.Serialization;

namespace GritTrack.Models
{
    public class Course
    {
        public int ID { get; set; }
        public string Name { get; set; } = string.Empty;
        public string CourseCode { get; set; } = string.Empty;
        public string Instructor { get; set; } = string.Empty;
        public double Credits { get; set; }
        public string CurrentGrade { get; set; } = string.Empty; // letter grade, e.g. "A-"
        public double GradePoints { get; set; }                  // e.g. 3.7
        public List<Assignment> Assignments { get; set; } = new();

        [JsonIgnore]
        public int CompletedCount => Assignments.Count(assignment => assignment.IsCompleted);

        [JsonIgnore]
        public int TotalCount => Assignments.Count;

        public override string ToString() => $"{CourseCode} - {Name}";
    }

    // Wrapper class matches the project's established JSON-persistence pattern
    public class CoursesJson
    {
        public List<Course> Courses { get; set; } = new();
    }
}

// ============================================================================
// CourseService - business logic for courses lives here
// grade calculations, validation, the stuff controllers shouldn't do
// ============================================================================

using GritTrack.Api.DTOs;
using GritTrack.Api.Models;
using GritTrack.Api.Repositories;
using Microsoft.EntityFrameworkCore;

namespace GritTrack.Api.Services;

public class CourseService : ICourseService
{
    private readonly ICourseRepository _repository;

    // same grade table the MAUI app uses - keep these in sync or GPA goes wonky
    private static readonly Dictionary<string, double> GradeTable = new(StringComparer.OrdinalIgnoreCase)
    {
        { "A", 4.0 }, { "A-", 3.7 },
        { "B+", 3.3 }, { "B", 3.0 }, { "B-", 2.7 },
        { "C+", 2.3 }, { "C", 2.0 }, { "C-", 1.7 },
        { "D+", 1.3 }, { "D", 1.0 }, { "D-", 0.7 },
        { "F", 0.0 }
    };

    private readonly ILogger<CourseService> _logger;

    public CourseService(ICourseRepository repository, ILogger<CourseService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    // get all courses, optionally filter by grade letter
    public async Task<List<Course>> GetCoursesAsync(string? grade, CancellationToken cancellationToken)
    {
        var courses = await _repository.GetAllAsync(cancellationToken);

        if (!string.IsNullOrWhiteSpace(grade))
        {
            courses = courses
                .Where(course => string.Equals(course.CurrentGrade, grade, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        return courses;
    }

    // straightforward lookup by id
    public Task<Course?> GetCourseByIdAsync(int id, CancellationToken cancellationToken)
        => _repository.GetByIdAsync(id, cancellationToken);

    // create course - but check for duplicate course codes first
    public async Task<(SaveCourseOutcome Outcome, Course? Course)> CreateCourseAsync(CourseRequestDto request, CancellationToken cancellationToken)
    {
        // no two courses can have the same code - that's our uniqueness rule
        // trim first, because " CS201 " gets saved as "CS201" and would sneak past the check
        var existing = await _repository.GetByCourseCodeAsync(request.CourseCode.Trim(), cancellationToken);
        if (existing is not null)
            return (SaveCourseOutcome.DuplicateCourseCode, null);

        var course = new Course
        {
            Name = request.Name.Trim(),
            CourseCode = request.CourseCode.Trim(),
            Instructor = request.Instructor?.Trim(),
            Credits = request.Credits,
            CurrentGrade = request.CurrentGrade.Trim(),
            GradePoints = GetGradePoints(request.CurrentGrade),
            CreatedAt = DateTime.UtcNow
        };

        try
        {
            var saved = await _repository.AddAsync(course, cancellationToken);
            _logger.LogInformation("Course created: id {CourseId}, code {CourseCode}", saved.Id, ForLog(saved.CourseCode));
            return (SaveCourseOutcome.Created, saved);
        }
        catch (DbUpdateException)
        {
            _logger.LogWarning("Duplicate course code race condition on create: {CourseCode}", ForLog(course.CourseCode));
            return (SaveCourseOutcome.DuplicateCourseCode, null);
        }
    }

    // update course - 404 if not found, 409 if code would collide with another course
    public async Task<(SaveCourseOutcome Outcome, Course? Course)> UpdateCourseAsync(int id, CourseRequestDto request, CancellationToken cancellationToken)
    {
        var existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null)
            return (SaveCourseOutcome.NotFound, null);

        // can keep your own code, but can't steal someone else's
        var codeOwner = await _repository.GetByCourseCodeAsync(request.CourseCode.Trim(), cancellationToken);
        if (codeOwner is not null && codeOwner.Id != id)
            return (SaveCourseOutcome.DuplicateCourseCode, null);

        existing.Name = request.Name.Trim();
        existing.CourseCode = request.CourseCode.Trim();
        existing.Instructor = request.Instructor?.Trim();
        existing.Credits = request.Credits;
        existing.CurrentGrade = request.CurrentGrade.Trim();
        existing.GradePoints = GetGradePoints(request.CurrentGrade);

        try
        {
            await _repository.UpdateAsync(existing, cancellationToken);
            _logger.LogInformation("Course updated: id {CourseId}, code {CourseCode}", existing.Id, ForLog(existing.CourseCode));
            return (SaveCourseOutcome.Updated, existing);
        }
        catch (DbUpdateException)
        {
            _logger.LogWarning("Duplicate course code race condition on update: {CourseCode}", ForLog(existing.CourseCode));
            return (SaveCourseOutcome.DuplicateCourseCode, null);
        }
    }

    // delete course - grab info first so we can log what got deleted
    public async Task<bool> DeleteCourseAsync(int id, CancellationToken cancellationToken)
    {
        var existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null)
            return false;

        var code = existing.CourseCode;
        var deleted = await _repository.DeleteAsync(id, cancellationToken);
        if (deleted)
            _logger.LogInformation("Course deleted: id {CourseId}, code {CourseCode}", id, ForLog(code));

        return deleted;
    }

    // sanitize for logging - prevent log injection via control chars
    private static string ForLog(string text)
        => new(text.Where(character => !char.IsControl(character)).ToArray());

    // letter grade to GPA points - unknown grades = 0 (harsh but fair)
    private static double GetGradePoints(string letterGrade)
        => GradeTable.TryGetValue(letterGrade.Trim(), out var points) ? points : 0.0;
}

// ============================================================================
// JsonCourseRepository - stores courses in a JSON file
// good for local dev, not for production. thread-safe via semaphore.
// ============================================================================

using System.Text.Json;
using GritTrack.Api.Models;

namespace GritTrack.Api.Repositories;

public class JsonCourseRepository : ICourseRepository
{
    private readonly string _filePath;
    private readonly SemaphoreSlim _fileLock = new(1, 1);

    private static readonly JsonSerializerOptions SerializerOptions = new()
    {
        WriteIndented = true
    };

    public JsonCourseRepository(IWebHostEnvironment environment)
    {
        var dataFolder = Path.Combine(environment.ContentRootPath, "Data");
        Directory.CreateDirectory(dataFolder);
        _filePath = Path.Combine(dataFolder, "courses.json");
    }

    /// <inheritdoc />
    public async Task<List<Course>> GetAllAsync(CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            return await ReadAllAsync(cancellationToken);
        }
        finally
        {
            _fileLock.Release();
        }
    }

    /// <inheritdoc />
    public async Task<Course?> GetByIdAsync(int id, CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var courses = await ReadAllAsync(cancellationToken);
            return courses.FirstOrDefault(course => course.Id == id);
        }
        finally
        {
            _fileLock.Release();
        }
    }

    /// <inheritdoc />
    public async Task<Course?> GetByCourseCodeAsync(string courseCode, CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var courses = await ReadAllAsync(cancellationToken);
            return courses.FirstOrDefault(course =>
                string.Equals(course.CourseCode, courseCode, StringComparison.OrdinalIgnoreCase));
        }
        finally
        {
            _fileLock.Release();
        }
    }

    /// <inheritdoc />
    public async Task<Course> AddAsync(Course course, CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var courses = await ReadAllAsync(cancellationToken);
            course.Id = courses.Count == 0 ? 1 : courses.Max(existing => existing.Id) + 1;
            courses.Add(course);

            await WriteAllAsync(courses, cancellationToken);
            return course;
        }
        finally
        {
            _fileLock.Release();
        }
    }

    /// <inheritdoc />
    public async Task<bool> UpdateAsync(Course course, CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var courses = await ReadAllAsync(cancellationToken);
            int index = courses.FindIndex(existing => existing.Id == course.Id);
            if (index < 0)
                return false;

            courses[index] = course;
            await WriteAllAsync(courses, cancellationToken);
            return true;
        }
        finally
        {
            _fileLock.Release();
        }
    }

    /// <inheritdoc />
    public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken)
    {
        await _fileLock.WaitAsync(cancellationToken);
        try
        {
            var courses = await ReadAllAsync(cancellationToken);
            int removed = courses.RemoveAll(course => course.Id == id);
            if (removed == 0)
                return false;

            await WriteAllAsync(courses, cancellationToken);
            return true;
        }
        finally
        {
            _fileLock.Release();
        }
    }

    // reads entire file - caller must hold the lock
    private async Task<List<Course>> ReadAllAsync(CancellationToken cancellationToken)
    {
        if (!File.Exists(_filePath))
            return new List<Course>();

        await using var stream = File.OpenRead(_filePath);
        if (stream.Length == 0)
            return new List<Course>();

        var courses = await JsonSerializer.DeserializeAsync<List<Course>>(stream, SerializerOptions, cancellationToken);
        return courses ?? new List<Course>();
    }

    // atomic write: temp file then rename, so no half-written files.
    // CancellationToken.None on purpose - a cancelled request shouldn't leave a torn temp file behind
    private async Task WriteAllAsync(List<Course> courses, CancellationToken cancellationToken)
    {
        var tempPath = _filePath + ".tmp";
        var json = JsonSerializer.Serialize(courses, SerializerOptions);
        await File.WriteAllTextAsync(tempPath, json, CancellationToken.None);

        File.Move(tempPath, _filePath, overwrite: true);
    }
}

using GritTrack.Api.Data;
using GritTrack.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace GritTrack.Api.Repositories;

/// <summary>Stores courses in SQL Server through EF Core. Same promises as the JSON repo, different home.</summary>
public class SqlCourseRepository : ICourseRepository
{
    private readonly GritTrackDbContext _context;

    public SqlCourseRepository(GritTrackDbContext context)
    {
        _context = context;
    }

    /// <inheritdoc />
    public Task<List<Course>> GetAllAsync(CancellationToken cancellationToken)
        => _context.Courses.AsNoTracking().OrderBy(course => course.Id).ToListAsync(cancellationToken);

    /// <inheritdoc />
    public Task<Course?> GetByIdAsync(int id, CancellationToken cancellationToken)
        => _context.Courses.FirstOrDefaultAsync(course => course.Id == id, cancellationToken);

    /// <inheritdoc />
    public Task<Course?> GetByCourseCodeAsync(string courseCode, CancellationToken cancellationToken)
    {
        // the column compares without caring about upper or lower case, same as the JSON repo
        string trimmedCode = courseCode.Trim();
        return _context.Courses.FirstOrDefaultAsync(course => course.CourseCode == trimmedCode, cancellationToken);
    }

    /// <inheritdoc />
    public async Task<Course> AddAsync(Course course, CancellationToken cancellationToken)
    {
        // SQL Server hands out the id when it saves
        _context.Courses.Add(course);
        await _context.SaveChangesAsync(cancellationToken);
        return course;
    }

    /// <inheritdoc />
    public async Task<bool> UpdateAsync(Course course, CancellationToken cancellationToken)
    {
        Course? stored = await _context.Courses.FirstOrDefaultAsync(existing => existing.Id == course.Id, cancellationToken);
        if (stored is null)
            return false;

        // when the caller already edited the tracked row itself there is nothing to copy
        if (!ReferenceEquals(stored, course))
            _context.Entry(stored).CurrentValues.SetValues(course);

        await _context.SaveChangesAsync(cancellationToken);
        return true;
    }

    /// <inheritdoc />
    public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken)
    {
        Course? stored = await _context.Courses.FirstOrDefaultAsync(course => course.Id == id, cancellationToken);
        if (stored is null)
            return false;

        _context.Courses.Remove(stored);
        await _context.SaveChangesAsync(cancellationToken);
        return true;
    }
}

