3	/// <summary>
4	/// Reads the repo's .env file (the same one docker compose uses) so the API and the
5	/// SQL container share one password. Real environment variables always win over the file.
6	/// </summary>
7	public static class DotEnvLoader
8	{
9	    /// <summary>Looks for .env in the start folder and then in each parent folder, and loads the first one it finds.</summary>
10	    public static void Load(string startFolder)
11	    {
12	        var folder = new DirectoryInfo(startFolder);
13	        while (folder is not null)
14	        {
15	            var filePath = Path.Combine(folder.FullName, ".env");
16	            if (File.Exists(filePath))
17	            {
18	                LoadFile(filePath);
19	                return;
20	            }
21	
22	            folder = folder.Parent;
23	        }
24	    }
25	
26	    /// <summary>Sets one environment variable for every NAME=value line, skipping blanks and # comments.</summary>
27	    private static void LoadFile(string filePath)
28	    {
29	        foreach (var rawLine in File.ReadAllLines(filePath))
30	        {
31	            var line = rawLine.Trim();
32	            if (line.Length == 0 || line.StartsWith('#'))
33	                continue;
34	
35	            var separatorIndex = line.IndexOf('=');
36	            if (separatorIndex <= 0)
37	                continue;
38	
39	            var name = line[..separatorIndex].Trim();
40	            var value = line[(separatorIndex + 1)..].Trim().Trim('"');
41	
42	            // a variable that is already set in the real environment wins
43	            if (Environment.GetEnvironmentVariable(name) is null)
44	                Environment.SetEnvironmentVariable(name, value);
45	        }
46	    }
47	}
