16	    {
17	        var REDACTED = configuration[PasswordKey];
18	        if (string.IsNullOrWhiteSpace(REDACTED))
19	        {
20	            throw new InvalidOperationException(
21	                $"DataSource is SqlServer but {PasswordKey} is not set. " +
22	                "Copy .env.example to .env and set it there (or use dotnet user-secrets).");
23	        }
24	
25	        return new SqlConnectionStringBuilder
26	        {
27	            DataSource = configuration["Database:Server"] ?? "127.0.0.1,1433",
28	            InitialCatalog = configuration["Database:Name"] ?? "GritTrack",
29	            UserID = "sa",
30	            Password = REDACTED,
31	            Encrypt = true,
32	            // the dev container uses a self-signed certificate
33	            TrustServerCertificate = true
34	        }.ConnectionString;
