3	namespace GritTrack.Services.Api
4	{
5	    // keeps the login token in SecureStorage (the phone/PC's protected store),
6	    // never in plain preferences or a file. the token is a "key card" the API
7	    // gave us at login; we show it on every write
8	    public class AuthService : IAuthService
9	    {
10	        public const string HttpClientName = "GritTrackAuth";
11	
12	        private const string TokenKey = "grittrack_token";
13	        private const string ExpiresKey = "grittrack_token_expires";
14	        private const string UserNameKey = "grittrack_user";
15	
16	        private readonly IHttpClientFactory _httpClientFactory;
17	        private readonly INavigationService _navigation;
18	
19	        // a copy kept in memory too, so the app still works if secure storage
20	        // isn't available on this machine
21	        private string? _token;
22	        private DateTime _expiresAtUtc;
23	        private TaskCompletionSource<bool>? _pendingLogin;
24	
25	        public AuthService(IHttpClientFactory httpClientFactory, INavigationService navigation)
26	        {
27	            _httpClientFactory = httpClientFactory;
28	            _navigation = navigation;
29	        }
30	
31	        public event EventHandler? SignInChanged;
32	
33	        public bool IsSignedIn => _token is not null && _expiresAtUtc > DateTime.UtcNow;
34	
35	        public string UserName { get; private set; } = string.Empty;
36	
37	        public async Task RestoreAsync()
38	        {
39	            try
40	            {
41	                var token = await SecureStorage.Default.GetAsync(TokenKey);
42	                var expires = await SecureStorage.Default.GetAsync(ExpiresKey);
43	                var userName = await SecureStorage.Default.GetAsync(UserNameKey);
44	
45	                if (token is not null && DateTime.TryParse(expires, null, System.Globalization.DateTimeStyles.RoundtripKind, out var expiresAtUtc))
46	                {
47	                    _token = token;
48	                    _expiresAtUtc = expiresAtUtc;
49	                    UserName = userName ?? string.Empty;
50	                }
51	            }
52	            catch (Exception)
53	            {
54	                // secure storage can be missing or locked. start signed out
55	            }
56	
57	            if (!IsSignedIn)
58	                await ClearAsync();
59	            else
60	                SignInChanged?.Invoke(this, EventArgs.Empty);
61	        }
62	
63	        public Task<string?> GetTokenAsync() => Task.FromResult(IsSignedIn ? _token : null);
64	
65	        public async Task SignInAsync(string userName, string REDACTED)
66	        {
67	            var client = _httpClientFactory.CreateClient(HttpClientName);
68	            using var request = new HttpRequestMessage(HttpMethod.Post, "api/auth/login")
69	            {
70	                Content = JsonContent.Create(new LoginRequest { UserName = userName, Password = REDACTED }, options: ApiResponseReader.JsonOptions)
71	            };
72	
73	            using var response = await ApiResponseReader.SendAsync(client, request);
74	
75	            // 401 here means a wrong user name or REDACTED, not "log in first"
76	            if (response.StatusCode == System.Net.HttpStatusCode.Unauthorized)
77	                throw new ApiValidationException(new[] { "User name or REDACTED is wrong." });
78	
79	            // 404 means the auth endpoint itself isn't available (Auth:Enabled is false)
80	            if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
81	                throw new ApiRequestException("Authentication is turned off on the server. Writes don't need a login right now.");
82	
83	            await ApiResponseReader.EnsureSuccessAsync(response);
84	
85	            var login = await response.Content.ReadFromJsonAsync<LoginResponse>(ApiResponseReader.JsonOptions);
86	            if (login is null || string.IsNullOrWhiteSpace(login.Token))
87	                throw new ApiRequestException("The server answered, but not with a login. Try again.");
88	
89	            _token = login.Token;
90	            _expiresAtUtc = login.ExpiresAtUtc.ToUniversalTime();
91	            UserName = userName.Trim();
92	
93	            try
94	            {
95	                await SecureStorage.Default.SetAsync(TokenKey, _token);
96	                await SecureStorage.Default.SetAsync(ExpiresKey, _expiresAtUtc.ToString("O"));
97	                await SecureStorage.Default.SetAsync(UserNameKey, UserName);
98	            }
99	            catch (Exception)
100	            {
101	                // couldn't save it for next time. the login still works for this run
102	            }
103	
104	            SignInChanged?.Invoke(this, EventArgs.Empty);
105	        }
106	
107	        public async Task SignOutAsync()
108	        {
109	            await ClearAsync();
110	        }
111	
112	        public async Task<bool> RequestLoginAsync()
113	        {
114	            // a login that was left open gets cancelled, so nothing waits forever
115	            _pendingLogin?.TrySetResult(false);
116	
117	            var pending = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
118	            _pendingLogin = pending;
119	
120	            await _navigation.GoToAsync(Routes.Login);
121	            return await pending.Task;
122	        }
123	
124	        public void CompleteLogin(bool signedIn)
125	        {
126	            _pendingLogin?.TrySetResult(signedIn);
127	            _pendingLogin = null;
128	        }
129	
130	        public async Task<T> RunWriteAsync<T>(Func<Task<T>> write)
131	        {
132	            try
133	            {
134	                return await write();
135	            }
136	            catch (AuthenticationRequiredException)
137	            {
138	                // no token, or an old one the server turned down: forget it, ask for a new login
139	                await ClearAsync();
140	
141	                if (!await RequestLoginAsync())
142	                    throw new LoginCancelledException();
143	
144	                return await write();
145	            }
146	        }
147	
148	        private async Task ClearAsync()
149	        {
150	            var wasSignedIn = _token is not null;
151	
152	            _token = null;
153	            _expiresAtUtc = DateTime.MinValue;
154	            UserName = string.Empty;
155	
156	            try
157	            {
158	                SecureStorage.Default.Remove(TokenKey);
159	                SecureStorage.Default.Remove(ExpiresKey);
160	                SecureStorage.Default.Remove(UserNameKey);
161	            }
162	            catch (Exception)
163	            {
164	                // nothing stored, or storage unavailable: either way we're signed out
165	            }
166	
167	            if (wasSignedIn)
168	                SignInChanged?.Invoke(this, EventArgs.Empty);
169	
170	            await Task.CompletedTask;
171	        }
172	    }
173	}
