307	        private async Task LoadCoursesAsync(bool forceReload)
308	        {
309	            if (_hasLoaded && !forceReload)
310	            {
311	                IsBusy = false;
312	                return;
313	            }
314	
315	            IsBusy = true;
316	            ErrorMessage = string.Empty;
317	
318	            try
319	            {
320	                var courses = await _courseRepository.GetCoursesAsync();
321	                var profile = await _gpaProfileRepository.GetProfileAsync();
322	
323	                // ObservableCollection changes must happen on the main thread
324	                MainThread.BeginInvokeOnMainThread(() =>
325	                {
326	                    Courses.Clear();
327	                    foreach (var course in courses)
328	                        Courses.Add(course);
329	
330	                    _startingGpa = profile.StartingGpa;
331	                    _startingCredits = profile.StartingCredits;
332	                    StartingGpaInput = _startingCredits > 0 ? _startingGpa.ToString("0.##") : string.Empty;
333	                    StartingCreditsInput = _startingCredits > 0 ? _startingCredits.ToString("0.##") : string.Empty;
334	
335	                    RecalculateGpa();
336	                });
337	
338	                _hasLoaded = true;
339	            }
340	            catch (Exception)
341	            {
342	                ErrorMessage = "Couldn't load your courses. Check that the API is running and try again.";
343	            }
344	            finally
345	            {
346	                IsBusy = false;
347	            }
348	        }
