459	        private void ApplyFilter()
460	        {
461	            FilteredCourses.Clear();
462	
463	            var query = SearchQuery?.Trim().ToLowerInvariant() ?? string.Empty;
464	
465	            foreach (var course in Courses)
466	            {
467	                if (string.IsNullOrEmpty(query) ||
468	                    course.Name.ToLowerInvariant().Contains(query) ||
469	                    course.CourseCode.ToLowerInvariant().Contains(query) ||
470	                    course.Instructor.ToLowerInvariant().Contains(query))
471	                {
472	                    FilteredCourses.Add(course);
473	                }
474	            }
475	        }
