477	        // open = grab the freshest assignments first, then build the sliders.
478	        // the Mid-State Hub saves imported assignments to a local file, and this
479	        // page loaded its courses long before that. without the refresh, the
480	        // simulator opened with nothing in it even right after an import
481	        private async Task ToggleSimulatorAsync()
482	        {
483	            if (IsSimulatorOpen)
484	            {
485	                IsSimulatorOpen = false;
486	                return;
487	            }
488	
489	            foreach (var course in Courses)
490	            {
491	                try
492	                {
493	                    course.Assignments = await _courseRepository.GetAssignmentsLocalAsync(course.ID);
494	                }
495	                catch (Exception)
496	                {
497	                    // can't read this course's file, so keep whatever it already had
498	                }
499	            }
500	
501	            BuildSimulationItems();
502	            IsSimulatorOpen = true;
503	        }
504	
505	        // one slider per assignment that isn't graded yet. worth 0 points = nothing
506	        // to simulate, so those stay out
507	        private void BuildSimulationItems()
508	        {
509	            SimulatedAssignments.Clear();
510	
511	            foreach (var course in Courses)
512	            {
513	                var ungradedAssignments = course.Assignments
514	                    .Where(assignment => (!assignment.IsCompleted || !assignment.PointsEarned.HasValue) && assignment.PointsPossible > 0);
515	
516	                foreach (var assignment in ungradedAssignments)
517	                {
518	                    SimulatedAssignments.Add(new SimulatedAssignmentItem
519	                    {
520	                        AssignmentId = assignment.ID,
521	                        CourseId = course.ID,
522	                        CourseCode = course.CourseCode,
523	                        Title = assignment.Title,
524	                        PointsPossible = assignment.PointsPossible,
525	                        ExpectedPoints = Math.Round(assignment.PointsPossible * 0.9),
526	                        OnScoreChanged = OnSimulatedScoreChanged
527	                    });
528	                }
529	            }
530	
531	            HasSimulatedAssignments = SimulatedAssignments.Count > 0;
532	            ScenarioPercent = 90;
533	            RecalculateSimulatedGpa();
534	        }
535	
536	        // preset buttons: "what if I get X% on everything coming up?"
537	        private void ApplyPresetScenario(string? percentText)
538	        {
539	            if (!double.TryParse(percentText, NumberStyles.Float, CultureInfo.InvariantCulture, out var percent))
540	                return;
541	
542	            // every slider fires its own change. hold the math until they're all set
543	            _isApplyingPreset = true;
544	            try
545	            {
546	                foreach (var simulatedAssignment in SimulatedAssignments)
547	                    simulatedAssignment.ExpectedPoints = Math.Round(simulatedAssignment.PointsPossible * (percent / 100.0));
548	            }
549	            finally
550	            {
551	                _isApplyingPreset = false;
552	            }
553	
554	            ScenarioPercent = percent;
555	            RecalculateSimulatedGpa();
556	        }
557	
558	        // you dragged a slider yourself, so it's no longer "X% on everything"
559	        private void OnSimulatedScoreChanged()
560	        {
561	            if (_isApplyingPreset)
562	                return;
563	
564	            ScenarioPercent = null;
565	            RecalculateSimulatedGpa();
566	        }
567	
568	        private void RecalculateSimulatedGpa()
569	        {
570	            var simulatedCourses = new List<Course>();
571	            SimulatedCourseResults.Clear();
572	
573	            foreach (var course in Courses)
574	            {
575	                var courseItems = SimulatedAssignments.Where(item => item.CourseId == course.ID).ToList();
576	
577	                // nothing simulated here, so this course keeps its real grade.
578	                // (rebuilding it from assignment points would make the GPA move
579	                // before you touched a single slider)
580	                if (courseItems.Count == 0)
581	                {
582	                    simulatedCourses.Add(course);
583	                    continue;
584	                }
585	
586	                var gradedAssignments = course.Assignments
587	                    .Where(assignment => assignment.IsCompleted && assignment.PointsEarned.HasValue && assignment.PointsPossible > 0)
588	                    .ToList();
589	
590	                var pointsEarned = gradedAssignments.Sum(assignment => assignment.PointsEarned!.Value);
591	                var pointsPossible = gradedAssignments.Sum(assignment => assignment.PointsPossible);
592	
593	                foreach (var simulatedAssignment in courseItems)
594	                {
595	                    pointsEarned += simulatedAssignment.ExpectedPoints;
596	                    pointsPossible += simulatedAssignment.PointsPossible;
597	                }
598	
599	                var percent = (pointsEarned / pointsPossible) * 100.0;
600	                var letterGrade = _gpaCalculator.GetLetterGradeFromPercent(percent);
601	
602	                simulatedCourses.Add(new Course
603	                {
604	                    ID = course.ID,
605	                    Name = course.Name,
606	                    Credits = course.Credits,
607	                    CurrentGrade = letterGrade,
608	                    GradePoints = _gpaCalculator.GetGradePoints(letterGrade)
609	                });
610	
611	                SimulatedCourseResults.Add(new SimulatedCourseResult
612	                {
613	                    CourseCode = string.IsNullOrWhiteSpace(course.CourseCode) ? course.Name : course.CourseCode,
614	                    CurrentGrade = course.CurrentGrade,
615	                    ProjectedGrade = letterGrade,
616	                    ProjectedPercent = percent
617	                });
618	            }
619	
620	            ProjectedGpa = _startingCredits > 0
621	                ? _gpaCalculator.CalculateGpa(simulatedCourses, _startingGpa, _startingCredits)
622	                : _gpaCalculator.CalculateGpa(simulatedCourses);
623	
624	            ProjectedStatus = _gpaCalculator.GetStatus(ProjectedGpa, PtkGoodStandingGpa, PtkInitiationGpa);
625	        }
626	
627	        private void RecalculateGpa()
628	        {
629	            ApplyFilter();
630	
631	            CurrentGpa = _startingCredits > 0
632	                ? _gpaCalculator.CalculateGpa(Courses, _startingGpa, _startingCredits)
633	                : _gpaCalculator.CalculateGpa(Courses);
634	
635	            Status = _gpaCalculator.GetStatus(CurrentGpa, PtkGoodStandingGpa, PtkInitiationGpa);
636	
637	            _themeService.ApplyGpaStatusTheme(Status);
638	
639	            if (IsSimulatorOpen)
640	                RecalculateSimulatedGpa();
641	        }
