644	        {
645	            if (course is null)
646	                return;
647	
648	            _ = _navigation.GoToAsync(
649	                Routes.CourseDetail,
650	                new Dictionary<string, object> { { QueryKeys.Course, course } });
651	        }
652	    }
653	}
