using System.Text.Json;
using GritTrack.Models;

namespace GritTrack.Services
{
    /// <summary>Persists assignments locally until the API supports them.</summary>
    public class LocalAssignmentStore
    {
        private readonly SemaphoreSlim _gate = new(1, 1);
        private Dictionary<int, List<Assignment>>? _assignmentsByCourseId;

        private static string FilePath => Path.Combine(FileSystem.AppDataDirectory, "local-assignments.json");

        public async Task<List<Assignment>> GetAsync(int courseId)
        {
            await _gate.WaitAsync();
            try
            {
                var all = await LoadAsync();
                if (!all.TryGetValue(courseId, out var assignments))
                    return new List<Assignment>();

                foreach (var assignment in assignments)
                    assignment.CourseID = courseId;

                return assignments.ToList();
            }
            finally
            {
                _gate.Release();
            }
        }

        public async Task<AssignmentImportResult> AddAsync(int courseId, IEnumerable<Assignment> assignments)
        {
            await _gate.WaitAsync();
            try
            {
                var all = await LoadAsync();
                if (!all.TryGetValue(courseId, out var existing))
                {
                    existing = new List<Assignment>();
                    all[courseId] = existing;
                }

                var result = AssignmentDuplicateRule.Filter(existing, assignments);

                if (result.AddedCount > 0)
                {
                    existing.AddRange(result.AddedAssignments);
                    await WriteAsync(all);
                }

                return result;
            }
            finally
            {
                _gate.Release();
            }
        }

        public async Task RemoveCourseAsync(int courseId)
        {
            await _gate.WaitAsync();
            try
            {
                var all = await LoadAsync();
                if (all.Remove(courseId))
                    await WriteAsync(all);
            }
            finally
            {
                _gate.Release();
            }
        }

        private async Task<Dictionary<int, List<Assignment>>> LoadAsync()
        {
            if (_assignmentsByCourseId is not null)
                return _assignmentsByCourseId;

            try
            {
                if (File.Exists(FilePath))
                {
                    var json = await File.ReadAllTextAsync(FilePath);
                    _assignmentsByCourseId = JsonSerializer.Deserialize<Dictionary<int, List<Assignment>>>(json);
                }
            }
            catch (Exception exception) when (exception is IOException or JsonException)
            {
                _assignmentsByCourseId = null;
            }

            return _assignmentsByCourseId ??= new Dictionary<int, List<Assignment>>();
        }

        private static async Task WriteAsync(Dictionary<int, List<Assignment>> all)
        {
            var json = JsonSerializer.Serialize(all);
            await File.WriteAllTextAsync(FilePath, json);
        }
    }
}

using System.Collections.ObjectModel;
using System.Globalization;
using GritTrack.Models;
using GritTrack.Services;
using GritTrack.Services.Api;

namespace GritTrack.PageModels
{
    public class CampusPortalItem
    {
        public string Name { get; set; } = string.Empty;
        public string Category { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public string Url { get; set; } = string.Empty;
        public string AccentHex { get; set; } = "#9fe0bd";

        public Color AccentTint => Color.FromArgb(AccentHex);
        public Brush AccentBrush => new SolidColorBrush(AccentTint);
    }

    public class MidStateHubPageModel : BaseViewModel
    {
        private readonly ICourseRepository _courseRepository;
        private readonly IAuthService _authService;

        public ObservableCollection<CampusPortalItem> Portals { get; }
        public ObservableCollection<Course> AvailableCourses { get; }

        public ObservableCollection<Assignment> ParsedAssignments { get; }

        public RelayCommand<string> OpenUrlCommand { get; }
        public RelayCommand ToggleCoursePickerCommand { get; }
        public RelayCommand<Course> SelectCourseCommand { get; }
        public RelayCommand ParseSyllabusCommand { get; }
        public RelayCommand ImportSyllabusCommand { get; }

        private Course? _selectedCourse;
        public Course? SelectedCourse
        {
            get => _selectedCourse;
            set
            {
                if (SetProperty(ref _selectedCourse, value))
                {
                    OnPropertyChanged(nameof(SelectedCourseDisplay));
                    ImportSyllabusCommand.RaiseCanExecuteChanged();
                }
            }
        }

        public string SelectedCourseDisplay
        {
            get
            {
                if (SelectedCourse is not null)
                    return $"{SelectedCourse.CourseCode} - {SelectedCourse.Name}";

                return HasNoCourses
                    ? "No courses yet. Add one on the Courses tab."
                    : "Tap to pick a course...";
            }
        }

        public bool HasNoCourses => AvailableCourses.Count == 0;

        private bool _isCoursePickerOpen;
        public bool IsCoursePickerOpen
        {
            get => _isCoursePickerOpen;
            set => SetProperty(ref _isCoursePickerOpen, value);
        }

        private string _syllabusRawText = string.Empty;
        public string SyllabusRawText
        {
            get => _syllabusRawText;
            set
            {
                if (SetProperty(ref _syllabusRawText, value))
                    ParsedAssignments.Clear();
            }
        }

        public bool HasParsedAssignments => ParsedAssignments.Count > 0;

        private bool _isImporting;

        private string _importStatusMessage = string.Empty;
        public string ImportStatusMessage
        {
            get => _importStatusMessage;
            set
            {
                if (SetProperty(ref _importStatusMessage, value))
                    OnPropertyChanged(nameof(HasImportStatusMessage));
            }
        }

        public bool HasImportStatusMessage => !string.IsNullOrWhiteSpace(ImportStatusMessage);

        private bool _isImportError;
        public bool IsImportError
        {
            get => _isImportError;
            set => SetProperty(ref _isImportError, value);
        }

        public MidStateHubPageModel(ICourseRepository courseRepository, IAuthService authService)
        {
            _courseRepository = courseRepository;
            _authService = authService;

            AvailableCourses = new ObservableCollection<Course>();
            ParsedAssignments = new ObservableCollection<Assignment>();

            Portals = new ObservableCollection<CampusPortalItem>
            {
                new()
                {
                    Name = "Blackboard Learn / Ultra",
                    Category = "LMS & Classes",
                    Description = "Mid-State course modules, assignment dropboxes, syllabus, and grades.",
                    Url = "https://mstc.blackboard.com",
                    AccentHex = "#9fe0bd"
                },
                new()
                {
                    Name = "Microsoft Teams",
                    Category = "Collaboration",
                    Description = "MSTC class channels, study sessions, and instructor office hours.",
                    Url = "https://teams.microsoft.com",
                    AccentHex = "#a3cbee"
                },
                new()
                {
                    Name = "Jira Software",
                    Category = "Collaboration",
                    Description = "Sprint planning boards, project backlogs, and issue tracking.",
                    Url = "https://www.atlassian.com/software/jira",
                    AccentHex = "#c3b0f2"
                },
                new()
                {
                    Name = "Mid-State Engage",
                    Category = "Student Life",
                    Description = "Campus events, PTK Beta Chi Theta meetings, and student organizations.",
                    Url = "https://mstc.campuslabs.com/engage/",
                    AccentHex = "#f2e3a6"
                },
                new()
                {
                    Name = "Microsoft MyApps (SSO)",
                    Category = "Portals & Admin",
                    Description = "Single sign-on launcher for Office 365, student email, and OneDrive.",
                    Url = "https://myapps.microsoft.com",
                    AccentHex = "#ffcfa6"
                },
                new()
                {
                    Name = "MyMSTC Student Center",
                    Category = "Portals & Admin",
                    Description = "Course registration, transcripts, financial aid, and billing.",
                    Url = "https://myportal.mywilm.com/psc/MSTC/EMPLOYEE/EMPL/c/NUI_FRAMEWORK.PT_LANDINGPAGE.GBL",
                    AccentHex = "#f6adbf"
                }
            };

            OpenUrlCommand = new RelayCommand<string>(url => _ = OpenPortalAsync(url));

            ToggleCoursePickerCommand = new RelayCommand(() =>
            {
                if (!IsCoursePickerOpen && AvailableCourses.Count == 0)
                    _ = LoadCoursesAsync();

                IsCoursePickerOpen = !IsCoursePickerOpen;
            });

            SelectCourseCommand = new RelayCommand<Course>(course =>
            {
                if (course is not null)
                    SelectedCourse = course;

                IsCoursePickerOpen = false;
            });

            ParseSyllabusCommand = new RelayCommand(ParseSyllabus);

            ImportSyllabusCommand = new RelayCommand(() => _ = ImportSyllabusAsync(), CanImport);

            ParsedAssignments.CollectionChanged += (_, _) =>
            {
                OnPropertyChanged(nameof(HasParsedAssignments));
                ImportSyllabusCommand.RaiseCanExecuteChanged();
            };
        }

        public async Task LoadCoursesAsync()
        {
            try
            {
                List<Course> courses = await _courseRepository.GetCoursesAsync();
                int? previousCourseId = SelectedCourse?.ID;

                AvailableCourses.Clear();
                foreach (Course loadedCourse in courses)
                    AvailableCourses.Add(loadedCourse);

                SelectedCourse = AvailableCourses.FirstOrDefault(availableCourse => availableCourse.ID == previousCourseId)
                    ?? AvailableCourses.FirstOrDefault();

                OnPropertyChanged(nameof(HasNoCourses));
                OnPropertyChanged(nameof(SelectedCourseDisplay));
            }
            catch (ApiRequestException exception)
            {
                ShowStatus(exception.Message, isError: true);
            }
            catch (Exception)
            {
                ShowStatus("Couldn't load your courses. Try switching tabs again.", isError: true);
            }
        }

        private async Task OpenPortalAsync(string? url)
        {
            if (string.IsNullOrWhiteSpace(url))
                return;

            try
            {
                await Launcher.Default.OpenAsync(new Uri(url));
            }
            catch (Exception)
            {
                ShowStatus("Couldn't open that link.", isError: true);
            }
        }

        private bool CanImport() => SelectedCourse is not null && ParsedAssignments.Count > 0 && !_isImporting;

        private void ParseSyllabus()
        {
            if (string.IsNullOrWhiteSpace(SyllabusRawText))
            {
                ShowStatus("Paste at least one syllabus line to parse.", isError: true);
                return;
            }

            string[] lines = SyllabusRawText.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            List<Assignment> parsedAssignments = new List<Assignment>();

            foreach (string line in lines)
            {
                string[] parts = line.Split('|', StringSplitOptions.TrimEntries);
                string title = parts[0];
                if (string.IsNullOrWhiteSpace(title))
                    continue;

                DateTime dueDate = parts.Length > 1 && DateTime.TryParse(parts[1], out DateTime parsedDate)
                    ? parsedDate
                    : DateTime.Today.AddDays(5);

                string pointsText = parts.Length > 2
                    ? new string(parts[2].Where(character => char.IsDigit(character) || character == '.').ToArray())
                    : string.Empty;
                double pointsPossible = double.TryParse(pointsText, NumberStyles.Float, CultureInfo.InvariantCulture, out double parsedPoints) && parsedPoints > 0
                    ? parsedPoints
                    : 50;

                parsedAssignments.Add(new Assignment
                {
                    ID = Random.Shared.Next(10000, 999999),
                    Title = title,
                    Type = AssignmentType.Homework,
                    DueDate = dueDate,
                    PointsPossible = pointsPossible,
                    Notes = "Imported from mstc.blackboard.com schedule"
                });
            }

            ParsedAssignments.Clear();

            if (parsedAssignments.Count == 0)
            {
                ShowStatus("Couldn't find any valid assignment titles to parse.", isError: true);
                return;
            }

            foreach (Assignment parsedAssignment in parsedAssignments)
                ParsedAssignments.Add(parsedAssignment);

            ShowStatus($"Found {ParsedAssignments.Count} assignment(s). Check them, then hit Import.", isError: false);
        }

        private async Task ImportSyllabusAsync()
        {
            Course? targetCourse = SelectedCourse;
            List<Assignment> importedAssignments = ParsedAssignments.ToList();

            if (targetCourse is null || importedAssignments.Count == 0)
                return;

            _isImporting = true;
            ImportSyllabusCommand.RaiseCanExecuteChanged();

            try
            {
                if (!_authService.IsSignedIn && !await _authService.RequestLoginAsync())
                    throw new LoginCancelledException();

                AssignmentImportResult result = await _courseRepository.SaveAssignmentsLocalAsync(targetCourse.ID, importedAssignments);

                foreach (Assignment addedAssignment in result.AddedAssignments)
                {
                    if (!targetCourse.Assignments.Contains(addedAssignment))
                        targetCourse.Assignments.Add(addedAssignment);
                }

                SyllabusRawText = string.Empty;

                string skippedNote = result.SkippedCount > 0 ? $" ({result.SkippedCount} duplicate(s) skipped)" : string.Empty;
                ShowStatus(
                    result.AddedCount > 0
                        ? $"Imported {result.AddedCount} assignment(s) to {targetCourse.Name}{skippedNote}."
                        : $"Nothing new: all {result.SkippedCount} were already in {targetCourse.Name}.",
                    isError: false);
            }
            catch (Exception exception) when (exception is ApiRequestException or LoginCancelledException)
            {
                ShowStatus(exception.Message, isError: true);
            }
            catch (Exception)
            {
                ShowStatus("Couldn't save the assignments on this phone. Try again.", isError: true);
            }
            finally
            {
                _isImporting = false;
                ImportSyllabusCommand.RaiseCanExecuteChanged();
            }
        }

        private void ShowStatus(string message, bool isError)
        {
            IsImportError = isError;
            ImportStatusMessage = message;
        }
    }
}

using System.Net.Http.Json;
using GritTrack.Models;

namespace GritTrack.Services.Api
{
    public class ApiCourseRepository : ICourseRepository
    {
        private readonly HttpClient _client;

        private readonly LocalAssignmentStore _assignmentStore;

        public ApiCourseRepository(HttpClient client, LocalAssignmentStore assignmentStore)
        {
            _client = client;
            _assignmentStore = assignmentStore;
        }

        public async Task<List<Course>> GetCoursesAsync()
        {
            using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, "api/courses");
            using HttpResponseMessage response = await ApiResponseReader.SendAsync(_client, request);
            await ApiResponseReader.EnsureSuccessAsync(response);

            List<CourseResponse>? courses = await response.Content.ReadFromJsonAsync<List<CourseResponse>>(ApiResponseReader.JsonOptions);
            List<Course> loadedCourses = courses?.Select(course => course.ToCourse()).ToList() ?? new List<Course>();

            foreach (Course loadedCourse in loadedCourses)
                loadedCourse.Assignments = await _assignmentStore.GetAsync(loadedCourse.ID);

            return loadedCourses;
        }

        public async Task<Course> SaveCourseAsync(Course course)
        {
            bool isNew = course.ID == 0;

            using HttpRequestMessage request = new HttpRequestMessage(
                isNew ? HttpMethod.Post : HttpMethod.Put,
                isNew ? "api/courses" : $"api/courses/{course.ID}")
            {
                Content = JsonContent.Create(CourseRequest.From(course), options: ApiResponseReader.JsonOptions)
            };

            using HttpResponseMessage response = await ApiResponseReader.SendAsync(_client, request);
            await ApiResponseReader.EnsureSuccessAsync(response);

            CourseResponse? saved = await response.Content.ReadFromJsonAsync<CourseResponse>(ApiResponseReader.JsonOptions);
            Course savedCourse = saved?.ToCourse() ?? throw new ApiRequestException("The server answered, but not with the saved course. Try again.");

            savedCourse.Assignments = await _assignmentStore.GetAsync(savedCourse.ID);
            return savedCourse;
        }

        public async Task DeleteCourseAsync(int courseId)
        {
            using HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Delete, $"api/courses/{courseId}");
            using HttpResponseMessage response = await ApiResponseReader.SendAsync(_client, request);
            await ApiResponseReader.EnsureSuccessAsync(response);

            await _assignmentStore.RemoveCourseAsync(courseId);
        }

        public Task<List<Assignment>> GetAssignmentsLocalAsync(int courseId)
        {
            return _assignmentStore.GetAsync(courseId);
        }

        public async Task<AssignmentImportResult> SaveAssignmentsLocalAsync(int courseId, IEnumerable<Assignment> assignments)
        {
            List<Assignment> assignmentList = assignments.ToList();
            foreach (Assignment assignment in assignmentList)
                assignment.CourseID = courseId;

            // TODO: Swap to batch POST /api/courses/{courseId}/assignments once backend endpoint is live
            return await _assignmentStore.AddAsync(courseId, assignmentList);
        }
    }
}

using GritTrack.PageModels;
using GritTrack.Pages;
using GritTrack.Services;
using GritTrack.Services.Api;
using Microsoft.Extensions.Logging;

namespace GritTrack
{
    public static class MauiProgram
    {
        public static MauiApp CreateMauiApp()
        {
            MauiAppBuilder builder = MauiApp.CreateBuilder();
            builder
                .UseMauiApp<App>()
                .ConfigureFonts(fonts =>
                {
                    fonts.AddFont("OpenSans-Regular.ttf", "OpenSansRegular");
                    fonts.AddFont("OpenSans-Semibold.ttf", "OpenSansSemibold");
                    fonts.AddFont("Kalam-Bold.ttf", "KalamBold");
                    fonts.AddFont("ArchitectsDaughter-Regular.ttf", "ArchitectsDaughter");
                });

#if DEBUG
            builder.Logging.AddDebug();
#endif
            // no state of its own, just math - fine to share one instance
            builder.Services.AddTransient<GpaCalculatorService>();

            // courses now come from the GritTrack API. the app never talks to
            // SQL Server itself: it only calls the API over HTTP.
            // BearerTokenHandler adds the login token to every write.
            // (InMemoryCourseRepository is still in Services/ for tests, but
            // it isn't registered here anymore)
            // keeps imported assignments in memory until the API can store them
            builder.Services.AddSingleton<LocalAssignmentStore>();

            builder.Services.AddSingleton<IAuthService, AuthService>();
            builder.Services.AddTransient<BearerTokenHandler>();

            // login's client has no bearer handler: it's how you get the token
            builder.Services.AddHttpClient(AuthService.HttpClientName, ConfigureApiClient)
                .ConfigurePrimaryHttpMessageHandler(DevelopmentHttpHandler.Create);

            // the courses client stamps the saved token on every request
            builder.Services.AddHttpClient<ICourseRepository, ApiCourseRepository>(ConfigureApiClient)
                .ConfigurePrimaryHttpMessageHandler(DevelopmentHttpHandler.Create)
                .AddHttpMessageHandler<BearerTokenHandler>();

            // same idea, for the starting GPA instead of courses
            builder.Services.AddSingleton<IGpaProfileRepository, InMemoryGpaProfileRepository>();

            builder.Services.AddSingleton<IThemeService, ThemeService>();
            builder.Services.AddSingleton<INavigationService, ShellNavigationService>();
            builder.Services.AddSingleton<AppShellViewModel>();
            builder.Services.AddSingleton<AppShell>();

            // a new ViewModel + Page each time you navigate to them
            builder.Services.AddTransient<CourseListPageModel>();
            builder.Services.AddTransient<CourseListPage>();
            builder.Services.AddTransient<CourseDetailPageModel>();
            builder.Services.AddTransient<CourseDetailPage>();
            builder.Services.AddTransient<AddCoursePageModel>();
            builder.Services.AddTransient<AddCoursePage>();
            builder.Services.AddTransient<LoginPageModel>();
            builder.Services.AddTransient<LoginPage>();
            builder.Services.AddTransient<MidStateHubPageModel>();
            builder.Services.AddTransient<MidStateHubPage>();

            return builder.Build();
        }

        // points an HttpClient at the API (the address depends on the device, see ApiSettings)
        private static void ConfigureApiClient(HttpClient client)
        {
            client.BaseAddress = new Uri(ApiSettings.BaseAddress);
            client.Timeout = ApiSettings.RequestTimeout;
        }
    }
}

// ============================================================================
// CourseService - business logic for courses lives here
// grade calculations, validation, the stuff controllers shouldn't do
// ============================================================================

using GritTrack.Api.DTOs;
using GritTrack.Api.Models;
using GritTrack.Api.Repositories;
using Microsoft.EntityFrameworkCore;

namespace GritTrack.Api.Services;

public class CourseService : ICourseService
{
    private readonly ICourseRepository _repository;

    // same grade table the MAUI app uses - keep these in sync or GPA goes wonky
    private static readonly Dictionary<string, double> GradeTable = new(StringComparer.OrdinalIgnoreCase)
    {
        { "A", 4.0 }, { "A-", 3.7 },
        { "B+", 3.3 }, { "B", 3.0 }, { "B-", 2.7 },
        { "C+", 2.3 }, { "C", 2.0 }, { "C-", 1.7 },
        { "D+", 1.3 }, { "D", 1.0 }, { "D-", 0.7 },
        { "F", 0.0 }
    };

    private readonly ILogger<CourseService> _logger;

    public CourseService(ICourseRepository repository, ILogger<CourseService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    // get all courses, optionally filter by grade letter
    public async Task<List<Course>> GetCoursesAsync(string? grade, CancellationToken cancellationToken)
    {
        List<Course> courses = await _repository.GetAllAsync(cancellationToken);

        if (!string.IsNullOrWhiteSpace(grade))
        {
            courses = courses
                .Where(course => string.Equals(course.CurrentGrade, grade, StringComparison.OrdinalIgnoreCase))
                .ToList();
        }

        return courses;
    }

    // straightforward lookup by id
    public Task<Course?> GetCourseByIdAsync(int id, CancellationToken cancellationToken)
        => _repository.GetByIdAsync(id, cancellationToken);

    // create course - but check for duplicate course codes first
    public async Task<(SaveCourseOutcome Outcome, Course? Course)> CreateCourseAsync(CourseRequestDto request, CancellationToken cancellationToken)
    {
        // no two courses can have the same code - that's our uniqueness rule
        // trim first, because " CS201 " gets saved as "CS201" and would sneak past the check
        Course? existing = await _repository.GetByCourseCodeAsync(request.CourseCode.Trim(), cancellationToken);
        if (existing is not null)
            return (SaveCourseOutcome.DuplicateCourseCode, null);

        Course course = new Course
        {
            Name = request.Name.Trim(),
            CourseCode = request.CourseCode.Trim(),
            Instructor = request.Instructor?.Trim(),
            Credits = request.Credits,
            CurrentGrade = request.CurrentGrade.Trim(),
            GradePoints = GetGradePoints(request.CurrentGrade),
            CreatedAt = DateTime.UtcNow
        };

        try
        {
            Course saved = await _repository.AddAsync(course, cancellationToken);
            _logger.LogInformation("Course created: id {CourseId}, code {CourseCode}", saved.Id, ForLog(saved.CourseCode));
            return (SaveCourseOutcome.Created, saved);
        }
        catch (DbUpdateException)
        {
            _logger.LogWarning("Duplicate course code race condition on create: {CourseCode}", ForLog(course.CourseCode));
            return (SaveCourseOutcome.DuplicateCourseCode, null);
        }
    }

    // update course - 404 if not found, 409 if code would collide with another course
    public async Task<(SaveCourseOutcome Outcome, Course? Course)> UpdateCourseAsync(int id, CourseRequestDto request, CancellationToken cancellationToken)
    {
        Course? existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null)
            return (SaveCourseOutcome.NotFound, null);

        // can keep your own code, but can't steal someone else's
        Course? codeOwner = await _repository.GetByCourseCodeAsync(request.CourseCode.Trim(), cancellationToken);
        if (codeOwner is not null && codeOwner.Id != id)
            return (SaveCourseOutcome.DuplicateCourseCode, null);

        existing.Name = request.Name.Trim();
        existing.CourseCode = request.CourseCode.Trim();
        existing.Instructor = request.Instructor?.Trim();
        existing.Credits = request.Credits;
        existing.CurrentGrade = request.CurrentGrade.Trim();
        existing.GradePoints = GetGradePoints(request.CurrentGrade);

        try
        {
            await _repository.UpdateAsync(existing, cancellationToken);
            _logger.LogInformation("Course updated: id {CourseId}, code {CourseCode}", existing.Id, ForLog(existing.CourseCode));
            return (SaveCourseOutcome.Updated, existing);
        }
        catch (DbUpdateException)
        {
            _logger.LogWarning("Duplicate course code race condition on update: {CourseCode}", ForLog(existing.CourseCode));
            return (SaveCourseOutcome.DuplicateCourseCode, null);
        }
    }

    // delete course - grab info first so we can log what got deleted
    public async Task<bool> DeleteCourseAsync(int id, CancellationToken cancellationToken)
    {
        Course? existing = await _repository.GetByIdAsync(id, cancellationToken);
        if (existing is null)
            return false;

        string code = existing.CourseCode;
        bool deleted = await _repository.DeleteAsync(id, cancellationToken);
        if (deleted)
            _logger.LogInformation("Course deleted: id {CourseId}, code {CourseCode}", id, ForLog(code));

        return deleted;
    }

    // sanitize for logging - prevent log injection via control chars
    private static string ForLog(string text)
        => new(text.Where(character => !char.IsControl(character)).ToArray());

    // letter grade to GPA points - unknown grades = 0 (harsh but fair)
    private static double GetGradePoints(string letterGrade)
        => GradeTable.TryGetValue(letterGrade.Trim(), out double points) ? points : 0.0;
}

