1	using System.Net;
2	using System.Text.Json;
3	
4	namespace GritTrack.Services.Api
5	{
6	    // turns a failed HTTP answer into one of our own exceptions, and wraps the
7	    // "couldn't reach the server" cases. shared by the course and login calls
8	    public static class ApiResponseReader
9	    {
10	        public static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);
11	
12	        // sends the request. a dead network, a refused connection or a timeout
13	        // all become the same friendly ApiRequestException
14	        public static async Task<HttpResponseMessage> SendAsync(HttpClient client, HttpRequestMessage request)
15	        {
16	            try
17	            {
18	                return await client.SendAsync(request);
19	            }
20	            catch (Exception exception) when (exception is HttpRequestException or TaskCanceledException)
21	            {
22	                throw new ApiRequestException("Couldn't reach the GritTrack server. Check that the API is running and try again.");
23	            }
24	        }
25	
26	        // does nothing for a 2xx answer, otherwise throws the matching exception
27	        public static async Task EnsureSuccessAsync(HttpResponseMessage response)
28	        {
29	            if (response.IsSuccessStatusCode)
30	                return;
31	
32	            switch (response.StatusCode)
33	            {
34	                case HttpStatusCode.Unauthorized:
35	                    throw new AuthenticationRequiredException();
