28	        public bool IsBusy
29	        {
30	            get => _isBusy;
31	            set => SetProperty(ref _isBusy, value);
32	        }
33	
34	        private string _errorMessage = string.Empty;
35	        public string ErrorMessage
36	        {
37	            get => _errorMessage;
38	            set
39	            {
40	                SetProperty(ref _errorMessage, value);
41	                OnPropertyChanged(nameof(HasError));
42	            }
43	        }
