45	        public bool HasError => !string.IsNullOrEmpty(ErrorMessage);
46	
47	        public RelayCommand GoBackCommand { get; }
48	        public RelayCommand EditCommand { get; }
49	
50	        public RelayCommand DeleteCommand { get; }
51	        public RelayCommand ConfirmDeleteCommand { get; }
