53	
54	        public CourseDetailPageModel(INavigationService navigation, ICourseRepository courseRepository, IAuthService authService)
55	        {
56	            _navigation = navigation;
57	            _courseRepository = courseRepository;
58	            _authService = authService;
59	
60	            GoBackCommand = new RelayCommand(() => _ = _navigation.GoToAsync(Routes.Back));
61	            EditCommand = new RelayCommand(() => _ = _navigation.GoToAsync(
62	                Routes.AddCourse,
63	                new Dictionary<string, object> { { QueryKeys.EditCourse, Course } }));
64	            DeleteCommand = new RelayCommand(() => IsConfirmingDelete = true);
65	
66	            ConfirmDeleteCommand = new RelayCommand(() =>
67	            {
68	                IsConfirmingDelete = false;
69	                _ = DeleteAsync();
70	            });
71	            CancelDeleteCommand = new RelayCommand(() => IsConfirmingDelete = false);
72	        }
