408	        private async Task SaveStartingGpaAsync()
409	        {
410	            string? gpaText = StartingGpaInput?.Trim();
411	            string? creditsText = StartingCreditsInput?.Trim();
412	
413	            StartingGpaError = string.Empty;
414	            StartingCreditsError = string.Empty;
415	
416	            // both boxes empty = clear the starting GPA
417	            if (string.IsNullOrEmpty(gpaText) && string.IsNullOrEmpty(creditsText))
418	            {
419	                _startingGpa = 0;
420	                _startingCredits = 0;
421	                await _gpaProfileRepository.SaveProfileAsync(new GpaProfile { StartingGpa = 0, StartingCredits = 0 });
422	                RecalculateGpa();
423	                IsEditingStartingGpa = false;
424	                return;
425	            }
426	
427	            // check both boxes so every bad one lights up at the same time
428	            bool isGpaValid = double.TryParse(gpaText, out double gpa) && gpa >= 0 && gpa <= 4.0;
429	            bool areCreditsValid = double.TryParse(creditsText, out double credits) && credits > 0;
430	
431	            if (!isGpaValid)
432	                StartingGpaError = "GPA needs to be a number from 0.0 to 4.0.";
433	
434	            if (!areCreditsValid)
435	                StartingCreditsError = "Credits needs to be a number greater than 0.";
436	
437	            if (!isGpaValid || !areCreditsValid)
438	                return;
439	
440	            _startingGpa = gpa;
441	            _startingCredits = credits;
442	            await _gpaProfileRepository.SaveProfileAsync(new GpaProfile { StartingGpa = gpa, StartingCredits = credits });
443	
444	            RecalculateGpa();
445	            IsEditingStartingGpa = false;
446	        }
