448	        private int IndexOf(int courseId)
449	        {
450	            for (int courseIndex = 0; courseIndex < Courses.Count; courseIndex++)
451	            {
452	                if (Courses[courseIndex].ID == courseId)
453	                    return courseIndex;
454	            }
455	
456	            return -1;
457	        }
